CAT = "capswAdl"; SEG = "ADL"
# VLO 8: ADLs, growth and development, body systems and common alterations, health promotion, rehabilitation and restorative care.
Q = [
("When giving a bed bath, which area do you usually wash first?",
 "The eyes, with water only", ["The feet, with soap and water", "The back, with lotion", "The perineum, with soap"],
 "Work from cleanest to dirtiest: eyes first with water only, wiping from the inner to the outer corner with a clean part of the cloth for each eye."),
("How should perineal care be done for a female client?",
 "Front to back", ["Back to front", "In circles from the anus out", "Only when she is incontinent"],
 "Wiping front to back keeps bacteria from the anus away from the urethra, lowering the risk of urinary tract infection."),
("How should you check bath water temperature before a client gets in?",
 "With a thermometer or your wrist", ["With your fingertips quickly", "By asking the client to test it first", "By the colour of the steam"],
 "Use a thermometer or the inside of your wrist, which is more sensitive than fingertips. Many older clients have reduced feeling and could be scalded if they test it."),
("When dressing a client with a weak right arm, which arm goes into the sleeve first?",
 "The right arm", ["The left arm", "Both at the same time", "Whichever the client lifts"],
 "Dress the weak or affected side first and undress it last. This needs the least movement of the weak limb."),
("How often should a client who cannot move themselves usually be repositioned?",
 "At least every 2 hours", ["At least every 8 hours", "Once a shift", "Only when they complain"],
 "Repositioning at least every two hours, or as the care plan says, relieves pressure on bony areas and helps prevent pressure injuries."),
("Where do pressure injuries most often form?",
 "Over heels, hips and other bones", ["On the palms of the hands", "On the front of the thighs and shins", "On the upper chest"],
 "Pressure injuries form where skin is squeezed between bone and a surface: the sacrum, hips, heels, elbows, shoulder blades and back of the head."),
("You notice a red area on a client's hip that does not fade when pressed. What should you do?",
 "Report it, keep pressure off", ["Massage it firmly to restore blood flow", "Cover it with a heating pad", "Ignore it until it blisters"],
 "Redness that does not blanch is an early pressure injury. Keep pressure off the area and report it. Massaging reddened skin can cause more damage."),
("What position is a client in when sitting up in bed with the head raised 45 to 60 degrees?",
 "Fowler's position", ["Prone position", "Sims' position", "Trendelenburg position"],
 "Fowler's position raises the head of the bed about 45 to 60 degrees, helpful for breathing and eating. Sims' is a side-lying position and prone is face down."),
("How should a client with swallowing problems be positioned for meals?",
 "Upright at 90 degrees", ["Lying flat on the back", "Reclined at 30 degrees", "Lying on the left side, propped"],
 "Sitting fully upright, with the chin slightly tucked if the plan says so, reduces the risk of food going into the lungs. Keep them upright for about 30 minutes after eating."),
("Which is a sign of aspiration while a client is eating?",
 "Coughing and a wet voice", ["Asking for more salt", "Eating faster than usual at meals", "Leaving the crusts"],
 "Coughing, choking, a wet voice or watery eyes during meals can mean food or fluid is entering the airway. Stop feeding and report it."),
("A client is on thickened fluids. What should you do?",
 "Thicken fluids as ordered", ["Give water if they ask nicely", "Thin the fluid if it is too thick", "Let the family decide each day"],
 "The thickness is set by the team, often from a swallowing assessment. Giving thin liquids can cause choking or aspiration pneumonia."),
("Where should a urinary catheter drainage bag be kept?",
 "Below the bladder", ["On the client's chest", "Level with the bladder", "On the floor beside the bed"],
 "Keeping the bag below the bladder stops urine flowing back into the bladder, and keeping it off the floor prevents contamination."),
("Which is a normal age-related change?",
 "Thinner, drier skin", ["Sudden confusion", "New loss of bladder control", "Inability to feel pain"],
 "Skin becomes thinner, drier and more fragile with age. Sudden confusion or new incontinence are not normal ageing and should be reported."),
("Which normal adult pulse rate range is correct at rest?",
 "60 to 100 beats a minute", ["40 to 60 beats a minute", "100 to 140 beats a minute", "20 to 40 beats a minute"],
 "A normal resting adult pulse is 60 to 100 beats a minute. Report readings outside the range or a big change from the client's usual."),
("What is a normal resting respiratory rate for an adult?",
 "12 to 20 breaths a minute", ["4 to 8 breaths a minute", "24 to 32 breaths a minute", "30 to 40 breaths a minute"],
 "Adults normally breathe 12 to 20 times a minute at rest. Count for a full minute without telling the client, so they do not change their breathing."),
("A client with diabetes is shaky, sweaty and confused. What might this be?",
 "Low blood sugar", ["High blood pressure", "A urinary infection", "Dehydration only"],
 "Shakiness, sweating, hunger and confusion are signs of hypoglycemia. Report it at once and follow the plan of care, which often says to give fast-acting sugar if the client can swallow."),
("Why is foot care important for a client with diabetes?",
 "Small cuts can get serious", ["Their nails never grow", "Their feet sweat less", "It prevents high blood sugar levels"],
 "Diabetes can reduce feeling and blood flow in the feet, so a small cut may go unnoticed and become infected. Check feet daily and report any sores; nail cutting often needs a nurse or foot care specialist."),
("A client with COPD is short of breath. Which position usually helps?",
 "Upright, leaning forward", ["Lying flat on the back", "Lying face down", "With the head lower than the feet"],
 "Sitting upright and leaning slightly forward, arms resting on a table, lets the lungs expand. Lying flat makes breathing harder."),
("A client has swelling in both ankles that is new today. What should you do?",
 "Report it to the nurse", ["Raise the legs and say nothing", "Give extra fluids", "Massage it away"],
 "New swelling can signal heart, kidney or circulation problems. Report it so the nurse can assess; comfort measures follow the plan."),
("Which helps prevent constipation?",
 "Fluids, fibre and activity", ["Bed rest and less water", "White bread, cheese and rest", "Holding back the urge"],
 "Enough fluid, high-fibre foods, regular activity and answering the urge promptly keep bowels regular. Report a change in bowel habits."),
("What is the goal of restorative care?",
 "Help clients keep abilities", ["Do everything for the client", "Keep clients in bed to rest and heal", "Speed up daily care"],
 "Restorative care helps clients reach and keep their highest level of function. Doing tasks they can do themselves leads to loss of ability."),
("A client can brush her own teeth, but slowly. What should you do?",
 "Set her up and let her do it", ["Brush them yourself to save time", "Skip it when you are busy", "Ask her family to do it"],
 "Encouraging independence keeps abilities and dignity. Set up the supplies, give cues and help only with what she cannot do."),
("Which walking aid is held on the client's strong side?",
 "A cane", ["A walker", "A wheelchair", "A transfer belt"],
 "A cane is held on the strong side and moves forward with the weak leg, so it shares the weight on the weak side."),
("When helping a client walk with a gait belt, where should you stand?",
 "Behind, on the weak side", ["Directly in front of them", "Just ahead, on the strong side", "Two steps behind them"],
 "Standing slightly behind on the weak side, holding the gait belt, lets you support them and ease them down if they start to fall."),
("How should you clean dentures?",
 "Over a basin with a towel", ["In very hot water", "With bleach once a week overnight", "While they are in the mouth"],
 "Clean dentures over a basin with water and a towel in it, so they do not break if dropped. Hot water can warp them. Store them in water in a labelled cup."),
("According to Maslow, which needs come first?",
 "Physical needs", ["Self-esteem needs", "Love and belonging", "Self-actualization"],
 "Maslow's hierarchy puts physiological needs at the base: air, water, food, rest and elimination. Higher needs become a focus once these are met."),
("According to Erikson, what is the main task of late adulthood?",
 "Integrity versus despair", ["Trust versus mistrust", "Identity versus role confusion", "Industry versus inferiority"],
 "Erikson's last stage is integrity versus despair: looking back on life with a sense of meaning or regret. Reminiscing can support this."),
("A client returns from hospital weak after a hip fracture. Who usually plans their exercise program?",
 "A physiotherapist", ["A registered dietitian", "A recreation worker", "A pharmacist"],
 "Physiotherapists assess movement and plan exercises and mobility goals. The PSW helps the client do them as the plan of care directs."),
("Which helps a client sleep well?",
 "A calm bedtime routine", ["Coffee in the evening", "Bright lights at night", "Long naps late in the afternoon"],
 "Regular routines, a quiet dark room and limiting caffeine and late naps support sleep. Report ongoing sleep problems."),
("How should a client's fingernails be cleaned?",
 "Soak, then clean gently", ["Scrape with a sharp knife", "Cut them as short as possible", "Clean only if the family asks"],
 "Soaking softens debris so it can be cleaned gently with an orange stick or brush. Trimming follows policy, especially for clients with diabetes."),
("What should you do with a client's hearing aid at night?",
 "Remove it and store it safely", ["Leave it in while they sleep", "Soak it in water overnight", "Leave the battery door shut overnight"],
 "Remove the hearing aid at night, open the battery door or turn it off to save the battery, and store it in its labelled case. Water damages it."),
("Which is a common early sign of dehydration in an older adult?",
 "Dark urine and dry mouth", ["Pale urine and more voiding", "Weight gain and swelling", "Moist skin and drooling"],
 "Dark, strong urine, a dry mouth and less urine are early signs. Older adults may feel less thirsty, so offer fluids often and record intake as directed."),
("What is the purpose of range-of-motion exercises?",
 "To keep joints moving", ["To build big muscles quickly", "To treat a broken bone", "To replace walking"],
 "Range-of-motion exercises move each joint through its normal motion to prevent contractures and stiffness. Stop if the client has pain and report it."),
("A client's blood pressure is 120/80 mm Hg. What is the 80?",
 "The diastolic pressure", ["The systolic pressure", "The pulse pressure", "The heart rate per minute"],
 "The top number is systolic, the pressure when the heart beats; the bottom number is diastolic, the pressure when the heart rests between beats."),
("Which client should not have a rectal temperature taken?",
 "One after rectal surgery", ["One who is very thin and frail", "One who wears dentures", "One who is hard of hearing"],
 "Rectal temperatures are avoided after rectal surgery, with diarrhea or certain heart conditions. Follow the plan of care for which route to use."),
("Which is a sign of a urinary tract infection in an older adult?",
 "New or worse confusion", ["Improved appetite at meals", "Better sleep", "Clear, odourless urine"],
 "Older adults often show a UTI as new confusion or behaviour change rather than burning. Report it with any urine changes."),
]
